import{_ as a,o as s,c as e,a2 as o}from"./chunks/framework.CdvW4CUT.js";const m=JSON.parse('{"title":"5000ms 的超时：CI 单测抖动该怎么归因，什么时候不该改阈值","description":"同一个 job、同一项测试，覆盖率模式 5250ms 超时、普通轮次 3548ms 通过。直接原因是超时，但把它改成 6000ms 会让下一次真正的回归失去信号。","frontmatter":{"title":"5000ms 的超时：CI 单测抖动该怎么归因，什么时候不该改阈值","date":"2026-11-04T00:00:00.000Z","tags":["CI","测试稳定性","归因","质量工程"],"description":"同一个 job、同一项测试，覆盖率模式 5250ms 超时、普通轮次 3548ms 通过。直接原因是超时，但把它改成 6000ms 会让下一次真正的回归失去信号。"},"headers":[],"relativePath":"posts/ci-flake.md","filePath":"posts/ci-flake.md"}'),n={name:"posts/ci-flake.md"};function i(r,t,d,l,p,h){return s(),e("div",null,[...t[0]||(t[0]=[o(`<h1 id="_5000ms-的超时-ci-单测抖动该怎么归因-什么时候不该改阈值" tabindex="-1">5000ms 的超时：CI 单测抖动该怎么归因，什么时候不该改阈值 <a class="header-anchor" href="#_5000ms-的超时-ci-单测抖动该怎么归因-什么时候不该改阈值" aria-label="Permalink to &quot;5000ms 的超时：CI 单测抖动该怎么归因，什么时候不该改阈值&quot;">​</a></h1><h2 id="背景" tabindex="-1">背景 <a class="header-anchor" href="#背景" aria-label="Permalink to &quot;背景&quot;">​</a></h2><p>某 Agent 平台的合并前流水线里，一条桌面端渲染层 UI 单测超时。那轮变更的主题是空闲 CPU 占用优化，失败文件不在改动范围内。我要回答的不是“怎么变绿”，而是：产品回归、测试不稳定，还是 CI 负载抖动？</p><h2 id="现象" tabindex="-1">现象 <a class="header-anchor" href="#现象" aria-label="Permalink to &quot;现象&quot;">​</a></h2><p>同一个 job 里，同一条用例在覆盖率阶段跑了 5250ms，超过 5000ms 的单测上限，报 <code>Test timed out in 5000ms</code>；同一个 job 的普通渲染层轮次，该文件 9 项全过，首项 3548ms。</p><p>范围很局部：覆盖率整套 232 个文件、2069 项，231 个文件通过、1 个失败，2068 项通过、1 项超时；其余 5 个 job 全部成功。没有断言失败，失败发生在覆盖率阶段，不是打包或发布。</p><h2 id="排查-从假设到证据" tabindex="-1">排查：从假设到证据 <a class="header-anchor" href="#排查-从假设到证据" aria-label="Permalink to &quot;排查：从假设到证据&quot;">​</a></h2><p>先定原则：先确认失败发生在哪一层（产品逻辑／测试本身／运行环境／基础设施），再判断是不是本轮改动引入。每条假设都先写反证条件，避免只收集支持自己的证据。</p><h3 id="假设一-cpu-优化改坏了-ui-流程" tabindex="-1">假设一：CPU 优化改坏了 UI 流程 <a class="header-anchor" href="#假设一-cpu-优化改坏了-ui-流程" aria-label="Permalink to &quot;假设一：CPU 优化改坏了 UI 流程&quot;">​</a></h3><p>变更主题就在附近，先查它。把改动路径与失败用例的调用链、组件、测试配置交叉核对，也看新增状态钩子、头像动画和新测试的执行顺序。</p><p>证据是：失败用例、渲染层入口、测试配置都不在本轮改动范围内；相关图标不启用动画，新钩子会提前退出；DOM 模拟环境没有动画能力时不会创建眨眼计时器；新增的头像回归文件在该用例之后才执行。没有找到本轮改动影响失败路径的代码证据。</p><p>所以“产品回归”降权，但不归零。只排除了已识别的直接路径，不能从数学上排除所有间接影响。</p><h3 id="假设二-覆盖率插桩-并发负载把它推过线" tabindex="-1">假设二：覆盖率插桩 + 并发负载把它推过线 <a class="header-anchor" href="#假设二-覆盖率插桩-并发负载把它推过线" aria-label="Permalink to &quot;假设二：覆盖率插桩 + 并发负载把它推过线&quot;">​</a></h3><p>同 job 的普通轮次与覆盖率轮次，代码、提交、测试文件相同，差异主要是插桩和并发负载，这是最接近控制变量的一组。普通轮次 3548ms 通过，覆盖率轮次 5250ms 超时，差 1702ms；只有覆盖率模式失败，其余 job 正常。</p><p>这组证据支持“环境敏感／抖动”是合理解释。但没有 CI 资源采样，1702ms 无法分给 CPU、IO、调度或 GC 中的任何一项。<strong>“只在覆盖率失败”也可能是时序敏感的真实缺陷</strong>，不能一律归为抖动。</p><h3 id="假设三-新测试先跑-污染了环境" tabindex="-1">假设三：新测试先跑，污染了环境 <a class="header-anchor" href="#假设三-新测试先跑-污染了环境" aria-label="Permalink to &quot;假设三：新测试先跑，污染了环境&quot;">​</a></h3><p>查执行顺序：新增的头像回归文件在失败文件之后执行，没有“先污染、后失败”的顺序证据。这个假设不成立——至少在当前顺序下。但不能排除其他未识别的跨文件共享状态。</p><h3 id="假设四-日志里的覆盖率解析提示是直接原因" tabindex="-1">假设四：日志里的覆盖率解析提示是直接原因 <a class="header-anchor" href="#假设四-日志里的覆盖率解析提示是直接原因" aria-label="Permalink to &quot;假设四：日志里的覆盖率解析提示是直接原因&quot;">​</a></h3><p>相邻成功任务的日志里也有同一条提示。它影响覆盖率统计（文件被排除），不影响测试执行。这是共性噪声，不是直接原因。<strong>日志里最显眼的报错，不一定是根因。</strong></p><h3 id="假设五-当前代码必现失败" tabindex="-1">假设五：当前代码必现失败 <a class="header-anchor" href="#假设五-当前代码必现失败" aria-label="Permalink to &quot;假设五：当前代码必现失败&quot;">​</a></h3><p>Windows 本机用同一套渲染层／DOM 模拟／覆盖率配置单文件复验：9 项全过，测试 9.58 秒，完整命令 19.05 秒；同 job 普通轮次也 9 项全过；相邻流水线成功。这不支持“必现失败”，但不等同 Linux CI 的全量并发。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>一次单测超时</span></span>
<span class="line"><span>├─ 有断言失败吗？ ── 没有 ──→ 是耗时越线，不是逻辑错</span></span>
<span class="line"><span>├─ 只有覆盖率模式失败？ ── 是 ──→ 插桩 + 并发负载可疑</span></span>
<span class="line"><span>├─ 同文件单独跑能过吗？ ── 9/9 通过 ──→ 不是必现</span></span>
<span class="line"><span>├─ 其他 job 也挂了吗？ ── 5/5 成功 ──→ 不是全局故障</span></span>
<span class="line"><span>└─ 有同项耗时分布吗？ ── 没有 ──→ 只能定直接原因，不能定根因</span></span></code></pre></div><h3 id="归因方法-四类对照" tabindex="-1">归因方法：四类对照 <a class="header-anchor" href="#归因方法-四类对照" aria-label="Permalink to &quot;归因方法：四类对照&quot;">​</a></h3><p>拆成四类，是为了避免“一失败就改代码”或“一通过就说修好”。</p><ol><li><strong>同配置对照</strong>：同一 job 内普通轮次与覆盖率轮次。代码、提交、测试文件相同，差异在插桩与并发负载，最接近控制变量。</li><li><strong>单文件复验</strong>：在 Windows 本机用同一套配置只跑该文件。9/9 通过，说明当前代码不是必现失败，但不能替代 Linux CI 的全量并发。</li><li><strong>历史同项耗时</strong>：普通轮次 3548ms 是最近可用基线，失败轮 5250ms，差 1702ms。相邻成功流水线没有逐项耗时，不能当分布；缺少更早的序列，无法判断是偶发离群还是趋势。</li><li><strong>失败模式</strong>：只有覆盖率模式失败、只有 1 个文件／1 条用例失败、其余 5 个 job 成功。范围越局部，越支持环境敏感；但“局部”不等于“无害”，仍可能是时序敏感缺陷。</li></ol><p>四类证据合起来，只够把“产品回归”降权、把“环境敏感”抬上来，不够回答“慢在哪”。</p><h2 id="根因" tabindex="-1">根因 <a class="header-anchor" href="#根因" aria-label="Permalink to &quot;根因&quot;">​</a></h2><p><strong>查到了什么：</strong> 直接原因明确——Linux CI 的覆盖率阶段，这条 UI 用例执行 5250ms，超过 5000ms 上限，测试框架判超时；失败在渲染层覆盖率阶段，没有断言失败。</p><p><strong>没查到什么：</strong> 为什么这一轮比同 job 普通轮次慢 1702ms、恰好越线。现有证据只能支持“覆盖率插桩开销 + CI 并发负载／运行抖动”的合理推测；没有资源采样、没有分步耗时、没有多轮重复，无法把权重分给 CPU、IO、调度或 GC。也不能证明这是稳定修复。</p><p>已排除／不支持：本轮 CPU 改动直接破坏流程（未见调用路径证据）；新测试顺序污染（新文件在后执行）；覆盖率解析提示（成功任务同样存在）；全局 CI 故障（其余 5 个 job 成功）。</p><p>结论边界：这是“直接原因明确的单次环境敏感超时”，不是“已确认的产品回归”，也不是“已修复”。</p><h2 id="修复方案与取舍" tabindex="-1">修复方案与取舍 <a class="header-anchor" href="#修复方案与取舍" aria-label="Permalink to &quot;修复方案与取舍&quot;">​</a></h2><ul><li><strong>放宽 5000ms 或删断言</strong>：成本最低，立即解除阻塞。但没有证据表明预算不合理；会把接近上限的用例放进更宽松的预算，下一次真实回归更容易漏过。这是用验收标准的变化掩盖未知原因，不采用。</li><li><strong>原提交、原断言、原超时重跑失败 job</strong>：最小改动，能区分“偶发”与“稳定回归”，保留首轮对照。代价是要等 CI 资源，而且即使通过也不能证明根因消失。作为第一步。</li><li><strong>若重跑仍复现，再做分步耗时 + CI 资源采样</strong>：定位实际慢点，再决定优化测试、隔离资源还是调整预算。成本高，未复现时可能过度排查。条件执行。</li><li><strong>中长期改成 fake timers／事件驱动等待</strong>：从机制上降低对真实时钟和机器负载的敏感度，而不是改预算。会改变测试语义，需要评审。作为后续方向，不在归因阶段混做重构。</li></ul><p>最终选择：立即重跑 + 条件采样 + 后续改造，不调阈值。原始失败日志和 5000ms 断言原样保留，作为对照基线。</p><p>为什么不是 6000ms？把上限改成 6000ms，下一次同类用例即使明显变慢，只要没越过新上限，就会安静通过。我们失去的不是一次红灯，而是“它变慢了”这个信号本身。调阈值是改变验收标准，不是修复；只有在预算本身被证明错了的时候才成立。</p><h2 id="验证结果" tabindex="-1">验证结果 <a class="header-anchor" href="#验证结果" aria-label="Permalink to &quot;验证结果&quot;">​</a></h2><table tabindex="0"><thead><tr><th>观测项</th><th>数字</th><th>能说明什么</th><th>不能说明什么</th></tr></thead><tbody><tr><td>失败用例耗时</td><td>5250ms &gt; 5000ms，<code>Test timed out in 5000ms</code></td><td>直接原因是超时</td><td>为什么变慢</td></tr><tr><td>同 job 普通轮次同文件</td><td>9/9 通过，首项 3548ms</td><td>同配置下可通过</td><td>Linux 覆盖率并发下也稳定</td></tr><tr><td>覆盖率整套</td><td>232 文件：231 过／1 败；2069 项：2068 过／1 超时</td><td>失败高度局部化</td><td>不是整套崩溃</td></tr><tr><td>其余 job</td><td>5/5 成功</td><td>不是全局基础设施故障</td><td>其他流水线没有同类问题</td></tr><tr><td>Windows 单文件复验</td><td>9/9 通过；测试 9.58s；命令 19.05s</td><td>当前代码在另一环境可通过</td><td>等同 Linux CI 全量并发</td></tr><tr><td>稳定性</td><td>未证明</td><td>—</td><td>不能宣称“已修复”或“CI 已转绿”</td></tr></tbody></table><p>口径：5250ms／3548ms 是 Linux CI 中测试框架的单用例墙钟耗时，5000ms 是配置上限，不是整套或整个 job 的时长；2068 通过／1 超时指同一 job 的覆盖率整套；9.58s 是测试耗时，19.05s 是完整命令耗时；5/5 只说明同一条流水线的其余 job 正常。样本是 1 次失败 + 1 次单文件复验，没有资源采样、没有多轮重复、没有 Linux CI 重跑。</p><h2 id="复盘" tabindex="-1">复盘 <a class="header-anchor" href="#复盘" aria-label="Permalink to &quot;复盘&quot;">​</a></h2><p><strong>三条可迁移经验：</strong></p><ol><li>先回答“能不能复现”，再回答“为什么慢”。固定 job、阶段、用例、耗时、有无断言失败，保留原始日志；做完四类对照再决定改不改代码。</li><li>局部失败不等于无害，全局通过也不等于无关。只有覆盖率失败，既可能是抖动，也可能是时序敏感缺陷；“其余都过”不能替代资源证据，也不能替代重跑。</li><li>调阈值是改变验收标准，不是修复。该调的前提是预算本身错了：产品要求或测量口径变化、长期 p95/p99 超过旧阈值、调整有评审和记录。单次失败、归因未明、没有耗时分布时，先保留红灯。</li></ol><p><strong>局限：</strong> Linux CI 没有重跑，没做资源采样、分步耗时、多轮重复；没在 Linux 容器里单文件复验；没改断言或超时（有意为之）；没证明稳定修复，也没宣称 CI 转绿。下一步是原样重跑：复现就采样，不复现就记为环境敏感继续观察。重跑权限和是否接受风险由变更负责人决定。</p>`,42)])])}const b=a(n,[["render",i]]);export{m as __pageData,b as default};
